/bin/bash -lc "git diff --stat; git diff -- work/BACKLOG.md modeling_project/VALIDATION_MATRIX.md | head -75; .codex-test/run python - <<'PY'
import json, subprocess
from pathlib import Path
s=json.loads(Path('/tmp/wi051-native-status.json').read_text())
def walk(x):
 if isinstance(x,dict):
  if x.get('id')=='WI-051': print('Native item:',x)
  for v in x.values():walk(v)
 elif isinstance(x,list):
  for v in x:walk(v)
walk(s)
e=Path('work/analysis/20260911-230953_radius-ownership-evidence')
for name in ['inventory.json','results.json','checks.json','checks.py','probe.py','source-meaning.md']:
 p=e/name
 assert p.read_bytes()==subprocess.check_output(['git','show',f'2f8856b7:{p}']),p
print('Six evidence files match immutable commit.')
rows=[l for l in Path('modeling_project/VALIDATION_MATRIX.md').read_text().splitlines() if any(f'| SV-{n} |' in l for n in range(83,90))]
assert len(rows)==7 and all(l.endswith('| pending |') for l in rows)
print('SV-083 through SV-089: seven pending entries.')
p=Path('work/active/WI-051_mfe-model-owned-major-radius/spec.md')
print('Spec:',len(p.read_text().split()),'words; artifacts:',[x.name for x in p.parent.iterdir()])
PY"

